(()=>{const mobile=window.matchMedia('(max-width: 760px)');const panels=[...document.querySelectorAll('.book-sidebar')].map(p=>p.matches('details')?p:p.querySelector(':scope > details')).filter(Boolean);const sync=()=>panels.forEach(p=>{p.open=!mobile.matches});sync();mobile.addEventListener('change',sync);const links=[...document.querySelectorAll('.book-page-toc .book-toc a[href^="#"]')];const topics=links.map(a=>({a,heading:document.getElementById(decodeURIComponent(a.hash.slice(1)))})).filter(x=>x.heading);const updateTopic=()=>{if(!topics.length)return;const cutoff=window.innerHeight*.28;let current=topics[0];for(const topic of topics){if(topic.heading.getBoundingClientRect().top<=cutoff)current=topic;else break;}for(const topic of topics){if(topic===current)topic.a.setAttribute('aria-current','location');else topic.a.removeAttribute('aria-current');}};window.addEventListener('scroll',updateTopic,{passive:true});window.addEventListener('resize',updateTopic);updateTopic();const figures=[...document.querySelectorAll('.book-content figure:has(>figcaption)')];const tables=[...document.querySelectorAll('.book-content .output-table:has(>.table-caption),.book-content table:has(>caption[id^="tbl-"])')];for(const ref of document.querySelectorAll('.kb-crossref')){const target=document.getElementById(ref.dataset.kbTarget);if(!target)continue;const type=ref.dataset.kbRef;const node=type==='fig'?target.closest('figure'):target.closest('.output-table')||target.closest('table');const number=(type==='fig'?figures:tables).indexOf(node)+1;const span=ref.querySelector('.kb-ref-number');if(number>0&&span)span.textContent=String(number);}if(window.renderMathInElement){window.renderMathInElement(document.body,{delimiters:[{left:'$$',right:'$$',display:true},{left:'\\[',right:'\\]',display:true},{left:'\\begin{equation}',right:'\\end{equation}',display:true},{left:'\\begin{align}',right:'\\end{align}',display:true},{left:'\\begin{alignat}',right:'\\end{alignat}',display:true},{left:'\\begin{gather}',right:'\\end{gather}',display:true},{left:'\\begin{CD}',right:'\\end{CD}',display:true},{left:'\\(',right:'\\)',display:false},{left:'$',right:'$',display:false}],throwOnError:false});}})();(()=>{const groups=[...document.querySelectorAll('.book-page-toc .book-toc-section')];const sync=()=>{const active=document.querySelector('.book-page-toc .book-toc a[aria-current="location"]');const section=active?.closest('[data-toc-section]')?.dataset.tocSection;for(const group of groups)group.open=Boolean(section)&&group.dataset.tocGroup===section;};window.addEventListener('scroll',sync,{passive:true});window.addEventListener('resize',sync);sync();})();(()=>{for(const group of document.querySelectorAll('.book-page-toc .book-toc-section')){const link=group.querySelector(':scope > summary > a');if(!link)continue;link.addEventListener('click',event=>{event.preventDefault();group.open=!group.open;});}})();